/**
 * Harness ToolDescriptor types — generic projection of the backend
 * `ToolDescriptor` declaration.
 *
 * Tool exposure, catalog display, approval, and redaction are generated by the
 * backend registry; the UI renders these fields without a per-tool event
 * allowlist. Never pass free-form tool output through `unsafeHTML`/`innerHTML`.
 */

import type { TaskStatus } from "./runtime.js";

export type ToolEffectKind = "read" | "write" | "destructive" | "external";

export type ToolCapability = "vision" | "video" | "audio" | "network" | "text";

/** Generic display metadata declared by the tool. */
export interface ToolPresentation {
  label: string;
  group: string;
  groupLabel: string;
  danger: boolean;
  enabled: boolean;
  icon?: string | null;
}

/** Catalog entry produced by `GET /tools/catalog`. */
export interface ToolCatalogEntry extends ToolPresentation {
  id: string;
  name: string;
  description: string;
  effectKind: ToolEffectKind;
  requiresApproval: boolean;
  requiredCapabilities: ToolCapability[];
}

export interface ToolCatalogGroup {
  id: string;
  label: string;
  source: string;
  tools: ToolCatalogEntry[];
}

export interface ToolCatalog {
  groups: ToolCatalogGroup[];
}

/** Effective approval policy after the Workflow policy tightened the tool. */
export interface ToolApprovalPolicy {
  mandatory: boolean;
  timeoutSecs: number;
  reason?: string | null;
}

/** Public, secret-redacted tool-call metadata (never raw request JSON). */
export interface ToolCallMetadata {
  toolName: string;
  argumentsSummary: string;
  presentation?: ToolPresentation;
  requiredCapabilities: ToolCapability[];
  approval: ToolApprovalPolicy;
}

/** One exception that needs a person, shown before any configuration or coordination. */
export interface HarnessAttentionItem {
  id: string;
  kind: string;
  title: string;
  detail: string;
  occurredAt: string;
  taskId: string | null;
  runId: string | null;
  eventId: string | null;
  actionLabel: string | null;
}

export interface HarnessAttentionPage {
  items: HarnessAttentionItem[];
  total: number;
  limit: number;
  offset: number;
}

/** Current Workflow revision summary; the editor consumes the full definition in Task 11B. */
export interface HarnessWorkflowSummary {
  workflowId: string;
  objective: string;
  enabled: boolean;
  version: number;
  triggerLabel: string;
  nextRunAt: string | null;
  lastResult: string | null;
  updatedAt: string | null;
}

/** Workspace Harness statuses extend the platform Runtime TaskStatus union. */
export type HarnessTaskStatus =
  | TaskStatus
  | 'running'
  | 'scheduled'
  | 'pending'
  | 'unknown'
  | 'cancelled_unknown'
  | 'simulation';

/** Isolated child execution summary. It never shares the Main conversation context. */
export interface HarnessSubagentSummary {
  taskId: string;
  runId: string | null;
  status: HarnessTaskStatus;
  waitReason: string | null;
  recentResult: string | null;
  updatedAt: string | null;
}

export interface HarnessMainTaskSummary {
  taskId: string;
  runId: string | null;
  objective: string;
  status: HarnessTaskStatus;
  waitReason: string | null;
  recentResult: string | null;
  updatedAt: string | null;
  subagents: HarnessSubagentSummary[];
  subagentTotal: number;
}

/** Exception-first overview aggregate for one workspace. */
export interface HarnessOverview {
  attention: HarnessAttentionPage;
  workflows: HarnessWorkflowSummary[];
  coordination: HarnessMainTaskSummary[];
}

export interface HarnessSubagentPage {
  subagents: HarnessSubagentSummary[];
  total: number;
  limit: number;
  offset: number;
}

/** Declarative trigger. `cron` carries the expression; watch/event only an id. */
export type WorkflowTrigger =
  | { type: 'cron'; triggerId: string; expression: string }
  | { type: 'watch'; triggerId: string }
  | { type: 'event'; triggerId: string };

/**
 * Versioned Workflow declaration. Selectors and policies stay opaque JSON so
 * the editor can round-trip fields the UI does not interpret yet.
 */
export interface WorkflowDefinition {
  objective: string;
  trigger: WorkflowTrigger;
  deviceSelector: unknown;
  sourceSelector: unknown;
  toolIds: string[];
  skillRefs: string[];
  requiredCapabilities: string[];
  approvalPolicy: unknown;
  evidencePolicy: unknown;
}

export interface WorkflowRevision {
  workflowId: string;
  version: number;
  enabled: boolean;
  definition: WorkflowDefinition;
  createdAt: string;
  /** Next planned cron wake; null for disabled/watch/event workflows. */
  nextWakeAt?: string | null;
}

/** One versioned built-in template (X1). */
export interface HarnessWorkflowTemplate {
  id: string;
  version: number;
  title: string;
  description: string;
  definition: WorkflowDefinition;
}

export interface HarnessWorkflowTemplateList {
  templates: HarnessWorkflowTemplate[];
}

/**
 * Instantiation parameters. Selectors replace the template defaults and the
 * approval policy may only tighten the template's mandatory policy.
 */
export interface HarnessWorkflowTemplateInput {
  workflowId: string;
  deviceSelector: unknown;
  sourceSelector: unknown;
  approvalPolicy: unknown;
}

/**
 * Error shape accepted by the editor's field mapper. `ApiError` satisfies it;
 * keeping this structural avoids coupling the types module to the API client.
 */
export interface HarnessApiError extends Error {
  code: number;
  data?: unknown;
}

/** One historical stamped snapshot selectable for an isolated dry-run. */
export interface HarnessWorkflowSnapshot {
  seq: number;
  observedAt: string;
  declarationHash: string;
  driverVersion: string;
}

export interface HarnessWorkflowSnapshotList {
  workflowId: string;
  version: number;
  snapshots: HarnessWorkflowSnapshot[];
}

/** Isolated simulation Task/Run pair; never a production Run. */
export interface HarnessDryRunResult {
  taskId: string;
  runId: string;
}

/** Scheduler health status. `idle` is normal, never a stalled alias. */
export type HarnessSupervisorStatus = 'idle' | 'healthy' | 'stalled';

export type HarnessStalledReason =
  | 'tick_deadline_exceeded'
  | 'due_not_started'
  | 'clock_rollback';

/**
 * Facts from the single mutable supervisor_state row plus durable Workflow,
 * wake and Task projections. AI heartbeat is never part of liveness here.
 */
export interface HarnessSupervisorHealth {
  status: HarnessSupervisorStatus;
  stalledReason: HarnessStalledReason | null;
  stalledLabel: string | null;
  tickSeq: number;
  lastStartedAt: string | null;
  lastCompletedAt: string | null;
  /** Planned wake time only; it never promises on-time execution. */
  nextWakeAt: string | null;
  oldestPendingAt: string | null;
  schedulingDelaySeconds: number;
  activeMains: number;
  activeSubagents: number;
  enabledWorkflows: number;
  pendingWakes: number;
  lastError: string | null;
  /** True when no Main/Subagent is active; separate from scheduler health. */
  noNewRuns: boolean;
  observedAt: string;
}

/** One dead wake that can be retried in place under its original event ID. */
export interface HarnessDeadWake {
  eventId: string;
  taskId: string;
  failureReason: string | null;
  createdAt: string;
  retriedBy: string | null;
  retriedAt: string | null;
}

export interface HarnessSupervisor {
  health: HarnessSupervisorHealth;
  deadWakes: HarnessDeadWake[];
  canRetry: boolean;
  readOnly: boolean;
}

/** Generic read-only Run projection reused by the simulation page. */
export interface HarnessSimulationStep {
  id: string;
  name: string;
  args: unknown;
  output: string | null;
}

export interface HarnessSimulationError {
  type: string;
  message: string;
  occurredAt: string;
}

export interface HarnessSimulationOutcome {
  status: string;
  summary: string;
  observations: string[];
  evidenceRefs: string[];
  recommendedActions: string[];
}

export interface HarnessSimulationProjection {
  executionMode: 'simulation';
  readOnly: true;
  taskId: string;
  runId: string | null;
  status: HarnessTaskStatus;
  workflowId: string | null;
  workflowVersion: number | null;
  objective: string | null;
  snapshot: {
    seq: number | null;
    observedAt: string | null;
    declarationHash: string | null;
    driverVersion: string | null;
  };
  steps: HarnessSimulationStep[];
  evidence: string[];
  errors: HarnessSimulationError[];
  outcome: HarnessSimulationOutcome | null;
}

export type HarnessCompactionStatus =
  | 'matched'
  | 'hash_mismatch'
  | 'snapshot_missing'
  | 'snapshot_advanced'
  | 'boundary_mismatch'
  | 'boundary_unavailable'
  | 'stale_append';

/** One immutable event fact covered by the fixed boundary. */
export interface HarnessCompactionEvidence {
  seq: number;
  eventId: string;
  eventType: string;
  reference: string;
}

/** One locatable canonical difference; paths use JSON Pointer syntax. */
export interface HarnessCompactionDifference {
  path: string;
  rebuilt: unknown;
  snapshot: unknown;
}

/**
 * Read-only fixed-boundary comparison. `canonicalHash` is the temporary
 * rebuild; `snapshotCanonicalHash` is the snapshot at the same boundary.
 * `canReplace`/`readOnly` are per-caller permission facts.
 */
export interface HarnessCompactionComparison {
  projectionName: string;
  subjectId: string;
  projectionVersion: number;
  boundaryLastSeq: number;
  snapshotLastSeq: number | null;
  snapshotStateVersion: number | null;
  seqFirst: number | null;
  seqLast: number | null;
  lastCompleteSeq: number;
  observedHighWatermark: number;
  appendedDuringCompare: boolean;
  status: HarnessCompactionStatus;
  matched: boolean;
  canonicalHash: string;
  snapshotCanonicalHash: string | null;
  canonicalState: unknown;
  differences: HarnessCompactionDifference[];
  evidenceRefs: HarnessCompactionEvidence[];
  canReplace: boolean;
  readOnly: boolean;
}

/** The projection snapshot row after an explicit CAS replacement. */
export interface HarnessProjectionSnapshot {
  projectionName: string;
  subjectId: string;
  lastSeq: number;
  projectionVersion: number;
  stateVersion: number;
  stateJson: unknown;
  updatedAt: string;
}
